/* --- 3. 文字：黑字一行 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-videocall-card *:not(.msg-videocall-icon, .msg-videocall-icon *) {
  display: inline-flex !important;
