  flex-wrap: nowrap !important;
  align-items: center !important;
  gap: 0 !important;
  flex-shrink: 0 !important;
  width: auto !important;
  max-width: none !important;
  height: calc(var(--wx-font) * 1.45) !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  font-size: var(--wx-font) !important;
  font-weight: 400 !important;
  line-height: 1.45 !important;
  white-space: nowrap !important;
  word-break: keep-all !important;
  opacity: 1 !important;
  color: var(--wxc-ink) !important;
  -webkit-text-fill-color: var(--wxc-ink) !important;
  text-shadow: none !important;
}
/* 接通：时长前面加「通话时长」 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-videocall-card:not(.missed) > :not(.msg-videocall-icon):first-of-type::before,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-videocall-card:not(.missed) > .msg-videocall-icon + :not(.msg-videocall-icon)::before {
  content: var(--wxc-dur-label) !important;
  white-space: pre !important;
  display: inline !important;
  color: var(--wxc-ink) !important;
  -webkit-text-fill-color: var(--wxc-ink) !important;
  font-size: var(--wx-font) !important;
}
/* 接通：App 自带的「通话已结束」不要，只留时长
   文字块里时长排在最后，前面的都藏掉；没包标签的散字用字号 0 藏掉
   「通话时长」是 ::before 画的，字号单独写了，不受影响 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .msg-videocall-card:not(.missed) > :not(.msg-videocall-icon):has(> *) {
  font-size: 0 !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .msg-videocall-card:not(.missed) > :not(.msg-videocall-icon) > :not(:last-child) {
  display: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .msg-videocall-card:not(.missed) > :not(.msg-videocall-icon) > :last-child {
  font-size: var(--wx-font) !important;
}

/* --- 4. 图标：原图标藏掉，mask 画成黑色线条图标 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-videocall-card .msg-videocall-icon {
  display: block !important;
  position: relative !important;
  top: 0 !important;
  flex: 0 0 var(--wxc-icon) !important;
  align-self: center !important;
  width: var(--wxc-icon) !important;
  height: var(--wxc-icon) !important;
  min-width: 0 !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  background-image: none !important;
  background-color: var(--wxc-ink) !important;
  -webkit-mask: var(--wxc-ic-phone) center / contain no-repeat !important;
  mask: var(--wxc-ic-phone) center / contain no-repeat !important;
  font-size: 0 !important;
  color: transparent !important;
  order: 0 !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-videocall-card .msg-videocall-icon *,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-videocall-card .msg-videocall-icon::before,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-videocall-card .msg-videocall-icon::after {
  content: none !important;
  display: none !important;
}
/* 视频通话：摄像机 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-videocall-card:is([class*="video-call"], [class*="is-video"], [class*="type-video"], .video) .msg-videocall-icon {
  -webkit-mask-image: var(--wxc-ic-video) !important;
  mask-image: var(--wxc-ic-video) !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.bubble-me-custom, .msg-plain-me) .msg-videocall-card:is([class*="video-call"], [class*="is-video"], [class*="type-video"], .video) .msg-videocall-icon {
  -webkit-mask-image: var(--wxc-ic-video-me) !important;
  mask-image: var(--wxc-ic-video-me) !important;
}
/* 我方：图标放到最右 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.bubble-me-custom, .msg-plain-me) .msg-videocall-card .msg-videocall-icon {
  order: 99 !important;
}

/* --- 5. ✨ 摘要标记、› 箭头、圆形按钮不要；时长保留 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-videocall-card > :nth-child(n+3):not(.msg-videocall-icon),
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-videocall-card :is(svg, img):not(.msg-videocall-icon *) {
  display: none !important;
}

/* --- 6. 没接通：换成固定的字 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-videocall-card.missed > *:not(.msg-videocall-icon) {
  display: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-videocall-card.missed::after {
  display: inline-block !important;
  position: static !important;
  flex-shrink: 0 !important;
  order: 1 !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  font-size: var(--wx-font) !important;
  font-weight: 400 !important;
  line-height: 1.45 !important;
  white-space: nowrap !important;
  color: var(--wxc-ink) !important;
  -webkit-text-fill-color: var(--wxc-ink) !important;
  background: none !important;
  text-shadow: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.bubble-me-custom, .msg-plain-me) .msg-videocall-card.missed::after {
  content: var(--wxc-me-miss) !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.bubble-them-custom, .msg-plain-them) .msg-videocall-card.missed::after {
  content: var(--wxc-them-miss) !important;
}
/* App 带了更细的类名时自动换字（没有就不生效） */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.bubble-me-custom, .msg-plain-me) .msg-videocall-card.missed:is([class*="hangup"], [class*="hung"], [class*="cancel"])::after {
  content: var(--wxc-me-hangup) !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.bubble-them-custom, .msg-plain-them) .msg-videocall-card.missed:is([class*="hangup"], [class*="hung"], [class*="cancel"])::after {
  content: var(--wxc-them-hangup) !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.bubble-me-custom, .msg-plain-me) .msg-videocall-card.missed:is([class*="reject"], [class*="declin"], [class*="refus"])::after {
  content: var(--wxc-them-reject) !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.bubble-them-custom, .msg-plain-them) .msg-videocall-card.missed:is([class*="reject"], [class*="declin"], [class*="refus"])::after {
  content: var(--wxc-me-reject) !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【撤回消息 · 仿微信】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 和系统时间一样的白底小框 + #E3E3E3 细边框 + 灰字
   - 我方：「你撤回了一条消息 重新编辑」（重新编辑是蓝字）
   - 对方：「XX撤回了一条消息」，XX 是 App 自己写进去的对方名字，这里不改字，只改样子
   - App 原来的「点击查看」：我方变成「重新编辑」，对方藏掉
     我方 / 对方靠上一条消息是不是我方来认（.msg-recalled 本身不带方向）
   :not(#_k) 叠三层是为了压过 App 自带样式，不要删 */

/* --- 1. 行：居中 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-recalled {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  min-height: 0 !important;
  margin-top: 6px !important;
  margin-bottom: 6px !important;
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  background: transparent !important;
}

/* --- 2. 白底小框，跟系统时间同一套变量 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-recalled .msg-system {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 5px !important;
  width: fit-content !important;
  max-width: 80% !important;
  margin: 0 !important;
  padding: var(--wxts-pad) !important;
  box-sizing: border-box !important;
  background: var(--wxts-bg) !important;
  border: var(--wxts-border-w) solid var(--wxts-border) !important;
  border-radius: var(--wxts-radius) !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  font-size: var(--wxts-size) !important;
  font-style: normal !important;
  font-weight: 400 !important;
  line-height: 1.4 !important;
  color: var(--wxts-color) !important;
  -webkit-text-fill-color: var(--wxts-color) !important;
  text-shadow: none !important;
  text-align: center !important;
  white-space: nowrap !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-recalled .msg-system::before,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-recalled .msg-system::after {
  content: none !important;
  display: none !important;
}

/* 框跟着字走：按字的实际宽度算，不被外面压窄 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .msg-recalled .msg-system {
  display: inline-block !important;
  flex: none !important;
  width: max-content !important;
  min-width: max-content !important;
  max-width: none !important;
  height: auto !important;
  padding: 3px 8px !important;
  letter-spacing: 0 !important;
  transform: none !important;
  overflow: visible !important;
}

/* --- 3. 对方撤回：App 会带一个「点击查看」，整个藏掉，只留「XX撤回了一条消息」 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-recalled .msg-system > * {
  display: none !important;
}

/* --- 4. 我方撤回：App 不带「点击查看」，后面加蓝字「重新编辑」（只是字，点了没反应）
   靠「里面有没有子元素」分我方 / 对方，比看上一条消息是谁发的准 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .msg-recalled .msg-system:not(:has(> *))::after {
  content: var(--wxr-edit) !important;
  display: inline !important;
  position: static !important;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
  border: none !important;
  font-size: var(--wxts-size) !important;
  font-weight: 400 !important;
  line-height: 1.4 !important;
  color: var(--wxr-edit-color) !important;
  -webkit-text-fill-color: var(--wxr-edit-color) !important;
  text-decoration: none !important;
  pointer-events: none !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【定位 / 文件 / 名片 / 聊天记录 · 仿微信】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 四种卡都是白底小圆角 + 白色尖角（双方都一样，尖角对着头像中间）
   - 定位：地名粗黑字 + 地址灰字，下面一张 SVG 画的地图（没有路名，路线自己画的）
   - 文件：左边文件名 + 大小，右边 SVG 文件图标
   - 名片：头像 + 名字，左下角「个人名片」
   - 聊天记录：标题 + 三行灰字，左下角「聊天记录」
   文字都是 App 的真实数据，只改样子
   :not(#_k) 叠三层是为了压过上面气泡的规则，不要删 */

/* --- 0. 四种卡外层：没有内边距，底色白，尖角留着也是白色 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-loc-card, .msg-file-card, .cc-card, .msg-history-card) {
  background: transparent !important;
  padding: 0 !important;
  min-width: 0 !important;
  min-height: 0 !important;
  border: none !important;
  box-shadow: none !important;
  overflow: visible !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-loc-card, .msg-file-card, .cc-card, .msg-history-card)::before {
  content: "" !important;
  display: block !important;
  background: var(--wxk-bg) !important;
  z-index: 0 !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-loc-card, .msg-file-card, .cc-card, .msg-history-card)::after {
  content: none !important;
  display: none !important;
}

/* 四种卡共用：白底小圆角 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.msg-loc-card, .msg-file-card, .cc-card, .msg-history-card) {
  position: relative !important;
  box-sizing: border-box !important;
  width: var(--wxk-w) !important;
  min-width: 0 !important;
  /* 屏幕窄时跟着缩：减掉两边头像和留白，不会再压到头像上 */
  max-width: calc(100vw - var(--wx-avatar) * 2 - var(--wxk-side-gap)) !important;
  margin: 0 !important;
  background: var(--wxk-bg) !important;
  border: none !important;
  border-radius: var(--wxk-radius) !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  filter: none !important;
  transform: none !important;
  animation: none !important;
  overflow: hidden !important;
  cursor: pointer !important;
  z-index: 1 !important;
  text-align: left !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.msg-loc-card, .msg-file-card, .cc-card, .msg-history-card) * {
  text-shadow: none !important;
  -webkit-text-stroke: 0 !important;
}

/* ═══ 1. 定位 ═══ */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-loc-card {
  display: flex !important;
  flex-direction: column !important;
  height: auto !important;
  padding: 0 !important;
