div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-loc-card::before,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-loc-card::after {
  content: none !important;
  display: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-loc-card :is(.msg-loc-header, .msg-loc-info) {
  order: 1 !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  box-sizing: border-box !important;
  width: 100% !important;
  min-width: 0 !important;
  margin: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-loc-card > :is(.msg-loc-header, .msg-loc-info) {
  padding: 10px 13px 8px !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-loc-card > :is(.msg-loc-header, .msg-loc-info) :is(.msg-loc-header, .msg-loc-info) {
  padding: 0 !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-loc-card :is(.msg-loc-header, .msg-loc-info) :is(svg, img) {
  display: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-loc-card .msg-loc-name {
  display: block !important;
  min-width: 0 !important;
  max-width: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  font-size: 16px !important;
  font-weight: 500 !important;
  line-height: 1.35 !important;
  color: var(--wxk-title) !important;
  -webkit-text-fill-color: var(--wxk-title) !important;
  white-space: nowrap !important;
