  margin: 2px 0 0 !important;
  padding: 0 !important;
  font-size: 12px !important;
  font-weight: 400 !important;
  line-height: 1.35 !important;
  color: var(--wxk-sub) !important;
  -webkit-text-fill-color: var(--wxk-sub) !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-loc-card :is(.msg-loc-dist, .msg-loc-approx, .msg-loc-footer, .msg-loc-footer-text) {
