div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-loc-card .msg-loc-map > *,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-loc-card .msg-loc-map::before,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-loc-card .msg-loc-map::after {
  content: none !important;
  display: none !important;
}

/* ═══ 2. 文件 ═══ */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 12px !important;
