  min-height: 0 !important;
  padding: 0 16px 0 14px !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card::before,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card::after {
