div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card .msg-file-name {
  display: flex !important;
  min-width: 0 !important;
  max-width: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  white-space: nowrap !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card :is(.msg-file-name, .msg-file-name *) {
