}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card .msg-file-meta .msg-file-dot,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card .msg-file-meta .msg-file-dot ~ *,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card .msg-file-meta::before,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card .msg-file-meta::after,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card :is(.msg-file-tag, .msg-file-preview, .msg-file-ext) {
