}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card .msg-file-icon {
  order: 2 !important;
  flex: none !important;
  position: relative !important;
  display: block !important;
  width: 40px !important;
  height: 48px !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
