}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card .msg-file-icon > *,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card .msg-file-icon::before,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-file-card .msg-file-icon::after {
