/* ═══ 4. 聊天记录 ═══
   第一个子元素当标题，后面的是记录，最多三行；左下角「聊天记录」 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-history-card {
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  gap: 2px !important;
  height: auto !important;
  padding: 11px 14px 30px !important;
  overflow: visible !important;   /* 尖角画在卡片外面，不能裁 */
}
/* 跟头像之间留出尖角的位置 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.msg-me, .bubble-me-custom, .msg-plain-me) .msg-history-card {
  margin-right: var(--wxk-avatar-gap) !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.msg-them, .bubble-them-custom, .msg-plain-them) .msg-history-card {
  margin-left: var(--wxk-avatar-gap) !important;
}
/* 尖角：外层气泡那个这里出不来，改画在卡片自己身上 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-history-card)::before {
  content: none !important;
  display: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-history-card::before {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  top: calc(var(--wx-avatar) / 2 - var(--wx-tail) / 2 + var(--wx-tail-nudge)) !important;
  bottom: auto !important;
  width: var(--wx-tail) !important;
  height: var(--wx-tail) !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: var(--wx-tail-round) !important;
  background: var(--wxk-bg) !important;
  box-shadow: none !important;
  transform: rotate(45deg) !important;
  pointer-events: none !important;
  z-index: -1 !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.msg-me, .bubble-me-custom, .msg-plain-me) .msg-history-card::before {
  right: calc(-1 * var(--wx-tail) / 2) !important;
  left: auto !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) :is(.msg-them, .bubble-them-custom, .msg-plain-them) .msg-history-card::before {
  left: calc(-1 * var(--wx-tail) / 2) !important;
  right: auto !important;
}
/* App 自己加的「…」和「Chat History」两行不要（最后两个子元素，前两个永远留着） */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-history-card > :nth-last-child(-n+2):not(:first-child):not(:nth-child(2)) {
  display: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-history-card::after {
  content: "聊天记录" !important;
  display: block !important;
  position: absolute !important;
  left: 14px !important;
  bottom: 6px !important;
  font-size: 12px !important;
  line-height: 18px !important;
  color: var(--wxk-foot) !important;
  -webkit-text-fill-color: var(--wxk-foot) !important;
  background: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-history-card * {
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  max-width: 100% !important;
  font-size: 14px !important;
  font-weight: 400 !important;
  line-height: 1.5 !important;
  color: var(--wxk-meta) !important;
  -webkit-text-fill-color: var(--wxk-meta) !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-history-card > :first-child,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-history-card > :first-child * {
  font-size: 16px !important;
  font-weight: 500 !important;
  line-height: 1.4 !important;
  color: var(--wxk-title) !important;
  -webkit-text-fill-color: var(--wxk-title) !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-history-card > :first-child {
  margin-bottom: 3px !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-history-card :is(svg, img, [class*="footer"], [class*="foot"]) {
  display: none !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【输入框引用预览条 · 仿微信】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 点引用时：输入框下面出一条浅灰条「名字：被引用的文字 ⓧ」，和输入框一样宽
   底栏整体往上抬，正好放下这一条；不引用时一切照旧
   「正在回复 」几个字用缩进裁掉，只留名字
   :not(#_k) 叠三层是为了压过上面底栏的规则，不要删 */

/* --- 1. 有引用：底栏下留白加上预览条的高度，输入框和图标一起往上抬 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom:has(.input-reply-preview-bar) {
  --wxb-bottom: calc(var(--wxb-home) + var(--wxr-h) + var(--wxr-gap));
}

/* --- 2. 预览条：摆在输入框正下方，左右和输入框对齐 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom .input-reply-preview-bar {
  position: absolute !important;
  left: calc(var(--wxb-side) + var(--wxb-icon) + var(--wxb-gap)) !important;
  right: calc(var(--wxb-side) + var(--wxb-icon) * 2 + var(--wxb-gap2) + var(--wxb-gap)) !important;
  bottom: var(--wxb-home) !important;
  top: auto !important;
  z-index: 5 !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 8px !important;
  box-sizing: border-box !important;
  width: auto !important;
  height: var(--wxr-h) !important;
  min-height: 0 !important;
  max-height: var(--wxr-h) !important;
  margin: 0 !important;
  padding: 0 calc((var(--wxr-h) - var(--wxr-close)) / 2 + 2px) 0 12px !important;
  background: var(--wxr-bg) !important;
  border: none !important;
  border-radius: var(--wxr-radius) !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  transform: none !important;
  overflow: hidden !important;
  pointer-events: auto !important;
}
/* 输入框有字、右边变成发送键时，预览条跟着输入框一起变短 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom:has(.input-box-custom:not(:placeholder-shown)) .input-reply-preview-bar {
  right: calc(var(--wxb-side) + var(--wxb-send-w) + var(--wxb-gap2) + var(--wxb-icon) + var(--wxb-gap)) !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom .input-reply-preview-bar::before,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom .input-reply-preview-bar::after {
  content: none !important;
  display: none !important;
}

/* --- 3. 文字：名字：引用文字 一行，超长「…」 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom .input-reply-preview-content {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 0 !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom .input-reply-preview-content::before,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom .input-reply-preview-content::after {
  content: none !important;
  display: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom :is(.input-reply-preview-name, .input-reply-preview-name *, .input-reply-preview-text, .input-reply-preview-text *) {
  font-size: var(--wxr-size) !important;
  font-weight: 400 !important;
  line-height: 20px !important;
  color: var(--wxr-color) !important;
  -webkit-text-fill-color: var(--wxr-color) !important;
  text-shadow: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom .input-reply-preview-name {
  display: block !important;
  flex: none !important;
  min-width: 0 !important;
  max-width: 60% !important;
  margin: 0 !important;
  padding: 0 !important;
  text-indent: calc(-1 * var(--wxr-cut)) !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: clip !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom .input-reply-preview-name::before {
  content: none !important;
  display: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom .input-reply-preview-name::after {
  content: var(--wxr-sep) !important;
  display: inline !important;
  position: static !important;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom .input-reply-preview-text {
  display: block !important;
  flex: 1 1 0 !important;
  min-width: 0 !important;
  width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  text-indent: 0 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
/* 引用图片 / 表情包：小缩略图 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom :is(.input-reply-preview-media, .input-reply-preview-media img) {
  flex: 0 0 22px !important;
  width: 22px !important;
  height: 22px !important;
  max-width: 22px !important;
  max-height: 22px !important;
  margin: 0 !important;
  object-fit: cover !important;
  border-radius: 2px !important;
}

/* --- 4. ⓧ：灰色实心圆 + 白叉，原来的图标藏掉，点击照常 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom .input-reply-preview-close {
  position: static !important;
  flex: 0 0 var(--wxr-close) !important;
  display: block !important;
  width: var(--wxr-close) !important;
  height: var(--wxr-close) !important;
  min-width: var(--wxr-close) !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 50% !important;
  background: var(--wxr-close-icon) center / 100% 100% no-repeat, var(--wxr-close-bg) !important;
  box-shadow: none !important;
  color: transparent !important;
  font-size: 0 !important;
  opacity: 1 !important;
  transform: none !important;
  cursor: pointer !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .input-area-custom .input-reply-preview-close > * {
  display: none !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【输入框自动长高】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 没字时：和原来一模一样，固定 --wxb-cap-h 高（上面那段）
   有字时：字一行就还是一行高；换行了才往上长（底边不动），最多 --wxb-max-lines 行，再多就在框里滚
   新一点的 WebView 认 field-sizing，纯 CSS 就能长；不认就用 App 自己算的高度
   :not(#_k) 叠四层是为了压过上面输入框写死的高度，不要删 */

/* 胶囊：有字时高度跟着里面的字 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .input-area-custom *:has(> .input-box-custom:not(:placeholder-shown)) {
  align-items: flex-end !important;
  height: auto !important;
  min-height: var(--wxb-cap-h) !important;
  max-height: none !important;
  padding-top: calc((var(--wxb-cap-h) - var(--wxb-line-h)) / 2) !important;
  padding-bottom: calc((var(--wxb-cap-h) - var(--wxb-line-h)) / 2) !important;
}
/* 打字的那块：一行起步，最多 --wxb-max-lines 行 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .input-area-custom .input-box-custom.input-box-custom:not(:placeholder-shown) {
  height: var(--wxb-line-h) !important;   /* 不认 field-sizing 时保持一行，不会乱撑 */
  min-height: var(--wxb-line-h) !important;
  max-height: calc(var(--wxb-line-h) * var(--wxb-max-lines)) !important;
}
@supports (field-sizing: content) {
  div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .input-area-custom .input-box-custom.input-box-custom:not(:placeholder-shown) {
    field-sizing: content !important;
    height: auto !important;
  }
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【分边颜色 · 日夜共用】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 我方 / 对方的字色、语音图标、通话图标分开管，夜间两边颜色不一样
   日间值都和原来一样 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me) {
  --wx-bubble-text: var(--wx-me-text);
  --wxc-ink: var(--wxc-me-ink);
}
div.chat-detail-screen :is(.bubble-them-custom, .msg-plain-them) {
  --wx-bubble-text: var(--wx-them-text);
  --wxc-ink: var(--wxc-them-ink);
}
div.chat-detail-screen .voice-msg-me {
  --wx-voice-ink: var(--wx-voice-me-ink);
}
div.chat-detail-screen .voice-msg-them {
  --wx-voice-ink: var(--wx-voice-them-ink);
}
div.chat-detail-screen:not(#_k) .voice-msg-them .voice-play-btn {
  background-image: var(--wx-voice-them-icon-c) !important;
}
div.chat-detail-screen .voice-msg .voice-transcription {
  --wx-bubble-text: var(--wx-tr-text);
}

/* 夜间压暗壁纸：在消息列表上铺一层半透明黑，气泡在它上面不受影响
   日间 --wx-dim 没定义 = 透明，不起作用 */
div.chat-detail-screen:not(#_k):not(#_k) .chat-message-list-custom {
  box-shadow: inset 0 0 0 100vmax var(--wx-dim, transparent) !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【转账 + 红包 · 文字颜色走变量】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 日间白字（和原来一样），夜间 #C79A69（在【夜间】两段里改 --wxp-text / --wxp-foot-text）
   :not(#_k) 叠四层是为了压过上面转账那段写死的白色，不要删 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .msg-transfer-card :is(.msg-transfer-amount, .msg-transfer-amount *, .msg-transfer-subtitle, .msg-transfer-subtitle *),
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .msg-transfer-card::after,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .msg-redpacket-card .msg-transfer-subtitle:empty::before {
  color: var(--wxp-text) !important;
  -webkit-text-fill-color: var(--wxp-text) !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-transfer-card)::after {
  color: var(--wxp-foot-text) !important;
  -webkit-text-fill-color: var(--wxp-foot-text) !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【顶栏底色 · 加固】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* App 夜间自己给顶栏写了一层半透明底色，优先级比上面的高，把 --wx-hdr-bg 压掉了
   这里抬高优先级，日夜都只认 --wx-hdr-bg；:not(#_k) 叠四层不要删 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .chat-header-custom,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .chat-header-custom.glass-header {
  background: var(--wx-hdr-bg) !important;
  background-color: var(--wx-hdr-bg) !important;
  background-image: none !important;
  backdrop-filter: blur(var(--wx-hdr-blur)) saturate(1.8) !important;
  -webkit-backdrop-filter: blur(var(--wx-hdr-blur)) saturate(1.8) !important;
  opacity: 1 !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .chat-header-custom::before,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .chat-header-custom::after {
  content: none !important;
  display: none !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【输入框 · 去掉 App 原来的胶囊形状】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* App 自己给打字的那块（textarea）加了大圆角 + 裁切，
   字一多、框一长，左上 / 左下那几个字的角就被它的圆角切掉了
   这里把它的形状清空，只留外面那个 7px 小圆角的框；:not(#_k) 叠四层不要删 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .input-area-custom .input-box-custom.input-box-custom,
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .input-area-custom *:has(> .input-box-custom) > :not(.input-btn-mic) {
  border-radius: 0 !important;
  clip-path: none !important;
  -webkit-mask: none !important;
  mask: none !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .input-area-custom .input-box-custom.input-box-custom {
 font-size: 16px !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【长按消息菜单 · 仿微信】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 深灰圆角面板，按钮排成格子：上面图标、下面字，一行 --wxm-cols 个，多了自动换行
   每一行之间一条细分隔线；按钮还是 App 原来那几个，点了功能不变
   变量在文件开头【长按消息菜单 + 选中文字】
   :not(#_k) 叠三层是为了压过 App 自带样式，不要删 */

/* --- 1. 面板 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .ig-context-menu,
body:not(#_k):not(#_k):not(#_k) .ig-context-menu {
  display: grid !important;
  grid-template-columns: repeat(var(--wxm-cols), var(--wxm-item-w)) !important;
  grid-auto-rows: var(--wxm-item-h) !important;
  gap: 0 !important;
  width: max-content !important;
  min-width: 0 !important;
  max-width: calc(100vw - 24px) !important;
  padding: var(--wxm-pad) !important;
  box-sizing: border-box !important;
  background-color: var(--wxm-bg) !important;
  background-image: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent calc(var(--wxm-item-h) - 0.5px),
    var(--wxm-line) calc(var(--wxm-item-h) - 0.5px),
    var(--wxm-line) var(--wxm-item-h)
  ) !important;
  background-origin: content-box !important;
  background-clip: padding-box !important;
  /* 只在行和行之间画线，最后一行下面不画 */
  background-repeat: no-repeat !important;
  background-size: 100% calc(100% - var(--wxm-item-h)) !important;
  border: none !important;
  border-radius: var(--wxm-radius) !important;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.25) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  overflow: hidden !important;
}
/* App 自己加的分隔线、小标题不要 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .ig-context-menu > :not(.ig-menu-item),
body:not(#_k):not(#_k):not(#_k) .ig-context-menu > :not(.ig-menu-item) {
  display: none !important;
}

/* --- 2. 每个按钮：上图标、下文字 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .ig-context-menu .ig-menu-item,
body:not(#_k):not(#_k):not(#_k) .ig-context-menu .ig-menu-item {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  gap: var(--wxm-icon-gap) !important;
  width: var(--wxm-item-w) !important;
  height: var(--wxm-item-h) !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 2px !important;
  box-sizing: border-box !important;
  background: transparent !important;
  border: none !important;
  border-radius: 6px !important;
  box-shadow: none !important;
  font-size: var(--wxm-size) !important;
  font-weight: 400 !important;
  line-height: 1.2 !important;
  color: var(--wxm-text) !important;
  -webkit-text-fill-color: var(--wxm-text) !important;
  text-align: center !important;
  white-space: nowrap !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .ig-context-menu .ig-menu-item:active,
body:not(#_k):not(#_k):not(#_k) .ig-context-menu .ig-menu-item:active {
  background: var(--wxm-press) !important;
}
/* 里面所有字（包括红色的「删除」）一律白色 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .ig-context-menu .ig-menu-item *,
body:not(#_k):not(#_k):not(#_k) .ig-context-menu .ig-menu-item * {
  margin: 0 !important;
  font-size: var(--wxm-size) !important;
  color: var(--wxm-text) !important;
  -webkit-text-fill-color: var(--wxm-text) !important;
  white-space: nowrap !important;
}
/* 图标 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .ig-context-menu .ig-menu-item svg,
body:not(#_k):not(#_k):not(#_k) .ig-context-menu .ig-menu-item svg {
  display: block !important;
  flex: none !important;
  width: var(--wxm-icon) !important;
  height: var(--wxm-icon) !important;
  color: var(--wxm-text) !important;
  stroke: currentColor !important;
  order: -1 !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【选中文字 · 仿微信】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 长按选中气泡里的字：绿色半透明底，字色不变；两头的拖动柄跟着变绿
   拖动柄是系统画的：iOS 跟着光标色（caret-color）走，安卓大多跟系统强调色，改不了的话就是系统色 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them, .msg-translation-detached, .voice-transcription) {
  -webkit-user-select: text;
  user-select: text;
  caret-color: var(--wxsel-handle) !important;
  -webkit-tap-highlight-color: transparent !important;
}
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them, .msg-translation-detached, .voice-transcription)::selection,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them, .msg-translation-detached, .voice-transcription) *::selection {
  background: var(--wxsel-bg) !important;
  color: inherit !important;
  -webkit-text-fill-color: currentColor !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【长按菜单 · 长字换行】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 样子还是上面【长按消息菜单 · 仿微信】那套：深灰面板、白图标白字、行间一条细线
   这里只管字：每格图标都顶在同一高度，字放不下就换成两行，再多才截成「…」，不压到隔壁
   :not(#_k) 叠四层不要删 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .ig-context-menu .ig-menu-item,
body:not(#_k):not(#_k):not(#_k):not(#_k) .ig-context-menu .ig-menu-item {
  justify-content: flex-start !important;
  padding: 14px 2px 0 !important;
  overflow: hidden !important;
  white-space: normal !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .ig-context-menu .ig-menu-item :not(svg):not(svg *),
body:not(#_k):not(#_k):not(#_k):not(#_k) .ig-context-menu .ig-menu-item :not(svg):not(svg *) {
  display: -webkit-box !important;
  -webkit-box-orient: vertical !important;
  -webkit-line-clamp: 2 !important;
  max-width: 100% !important;
  overflow: hidden !important;
  white-space: normal !important;
  word-break: break-all !important;
  text-align: center !important;
  line-height: 1.3 !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【长按时浮起来的那条消息 · 仿微信】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 长按时 App 会把那条消息复制一份浮在菜单旁边，这份不在消息列表里，
   所以上面气泡的尖角、内边距都没套上。这里给它补上，并画成微信「全选」的样子：
   字底下一层绿色，左上、右下各一个绿色拖动柄（是画上去的，拖不动）
   颜色用文件开头的 --wxsel-bg / --wxsel-handle
   :not(#_k) 叠四层是为了压过 App 给这份复制写的样式，不要删 */
/* ⚠ 只认「菜单开着」+「不在消息行（.msg-bubble-wrapper）里」的那份，列表里的气泡不受影响 */
body:not(#_k):not(#_k):not(#_k):not(#_k):has(.ig-context-menu) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):not(.msg-bubble-wrapper *):not(:has(img, video, [class*="card"], [class*="sticker"], .voice-msg)) {
  position: relative !important;
  overflow: visible !important;
  box-sizing: border-box !important;
  padding: var(--wx-pad-y) var(--wx-pad-x) !important;
  border: none !important;
  border-radius: var(--wx-bubble-radius) !important;
  box-shadow: none !important;
  font-size: var(--wx-font) !important;
  line-height: 1.45 !important;
}
body:not(#_k):not(#_k):not(#_k):not(#_k):has(.ig-context-menu) :is(.bubble-me-custom, .msg-plain-me):not(.msg-bubble-wrapper *):not(:has(img, video, [class*="card"], [class*="sticker"], .voice-msg)) {
  background: var(--wx-me-bg) !important;
  --wx-bubble-text: var(--wx-me-text);
}
body:not(#_k):not(#_k):not(#_k):not(#_k):has(.ig-context-menu) :is(.bubble-them-custom, .msg-plain-them):not(.msg-bubble-wrapper *):not(:has(img, video, [class*="card"], [class*="sticker"], .voice-msg)) {
  background: var(--wx-them-bg) !important;
  --wx-bubble-text: var(--wx-them-text);
}
body:not(#_k):not(#_k):not(#_k):not(#_k):has(.ig-context-menu) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):not(.msg-bubble-wrapper *):not(:has(img, video, [class*="card"], [class*="sticker"], .voice-msg)),
body:not(#_k):not(#_k):not(#_k):not(#_k):has(.ig-context-menu) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):not(.msg-bubble-wrapper *):not(:has(img, video, [class*="card"], [class*="sticker"], .voice-msg)) * {
  color: var(--wx-bubble-text) !important;
  -webkit-text-fill-color: var(--wx-bubble-text) !important;
  font-size: var(--wx-font) !important;
}

/* 尖角：和列表里的一样 */
body:not(#_k):not(#_k):not(#_k):not(#_k):has(.ig-context-menu) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):not(.msg-bubble-wrapper *):not(:has(img, video, [class*="card"], [class*="sticker"], .voice-msg))::before {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  top: calc(var(--wx-avatar) / 2 - var(--wx-tail) / 2 + var(--wx-tail-nudge)) !important;
  bottom: auto !important;
  width: var(--wx-tail) !important;
  height: var(--wx-tail) !important;
  border: none !important;
  border-radius: var(--wx-tail-round) !important;
  transform: rotate(45deg) !important;
  pointer-events: none !important;
  z-index: 0 !important;
}
body:not(#_k):not(#_k):not(#_k):not(#_k):has(.ig-context-menu) :is(.bubble-me-custom, .msg-plain-me):not(.msg-bubble-wrapper *):not(:has(img, video, [class*="card"], [class*="sticker"], .voice-msg))::before {
  right: calc(-1 * var(--wx-tail) / 2) !important;
  left: auto !important;
  background: var(--wx-me-bg) !important;
}
body:not(#_k):not(#_k):not(#_k):not(#_k):has(.ig-context-menu) :is(.bubble-them-custom, .msg-plain-them):not(.msg-bubble-wrapper *):not(:has(img, video, [class*="card"], [class*="sticker"], .voice-msg))::before {
  left: calc(-1 * var(--wx-tail) / 2) !important;
  right: auto !important;
  background: var(--wx-them-bg) !important;
}

/* 全选效果：字底下一层绿 + 左上 / 右下两个拖动柄（柄 = 小圆点 + 竖线） */
body:not(#_k):not(#_k):not(#_k):not(#_k):has(.ig-context-menu) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):not(.msg-bubble-wrapper *):not(:has(img, video, [class*="card"], [class*="sticker"], .voice-msg))::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  /* 比文字区域上下各多 9px（放圆点），左右各多 3px（放竖线） */
  top: calc(var(--wx-pad-y) - 9px) !important;
  bottom: calc(var(--wx-pad-y) - 9px) !important;
  left: calc(var(--wx-pad-x) - 3px) !important;
  right: calc(var(--wx-pad-x) - 3px) !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  transform: none !important;
  background:
    /* 左上圆点 */
    radial-gradient(circle at 3px 5px, var(--wxsel-handle) 0 4.5px, transparent 5px) no-repeat,
    /* 左边竖线 */
    linear-gradient(var(--wxsel-handle), var(--wxsel-handle)) 2px 5px / 2px calc(100% - 14px) no-repeat,
    /* 右下圆点 */
    radial-gradient(circle at calc(100% - 3px) calc(100% - 5px), var(--wxsel-handle) 0 4.5px, transparent 5px) no-repeat,
    /* 右边竖线 */
    linear-gradient(var(--wxsel-handle), var(--wxsel-handle)) calc(100% - 2px) 9px / 2px calc(100% - 14px) no-repeat,
    /* 选中的绿底：正好盖住文字区域 */
    linear-gradient(var(--wxsel-bg), var(--wxsel-bg)) 3px 9px / calc(100% - 6px) calc(100% - 18px) no-repeat !important;
  pointer-events: none !important;
  z-index: 1 !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【功能菜单 · 仿微信底部面板】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 照搬「微信11.9」
   点最左的功能键：菜单不再是浮起来的小气泡，而是像微信一样
   从输入框下面展开一块面板，输入框和三个图标整体被顶上去
   - 一排 4 个、一页 2 排（8 个），多了往右滑翻页，松手自动吸附到整页
   - 每个按钮：白色圆角方块 + 深灰实心图标，下面一行灰字（夜间：深灰方块 + 浅灰图标）
   - 底下小圆点是页码（新一点的 WebView 会跟着滑动走；旧的就一直亮第一个）
   - 「自定义菜单」自动排在最后一格，中间那条分隔线不要
   按钮还是 App 原来那些，点了功能不变
   夜间颜色写在文件开头夜间那两段里（--wxo-tile-bg 那几行）
   :not(#_k) 叠四层是为了压过上面菜单和底栏的规则，不要删 */

:root,
div.chat-detail-screen {
  /* 🐕 */ --wxo-h: 270px;                  /* 面板总高度（含底下给 Home 条的留白） */
  /* 🐕 */ --wxo-pad-top: 14px;             /* 第一排离细线的距离，越小图标越靠上 */
  /* 🐕 */ --wxo-row-gap: 16px;             /* 两排之间的距离 */
  /* 🐕 */ --wxo-tile: 64px;                /* 白色方块边长 */
  /* 🐕 */ --wxo-tile-radius: 14px;         /* 方块圆角 */
  /* 🐕 */ --wxo-tile-bg: #FFFFFF;          /* 方块底色 */
  /* 🐕 */ --wxo-icon: 28px;                /* 方块里图标大小（认不出的原线条图标） */
  /* 🐕 */ --wxo-glyph: 36px;               /* 实心图标大小 */
  /* 🐕 */ --wxo-icon-color: #4C4C4C;       /* 图标颜色 */
  /* 🐕 */ --wxo-icon-stroke: 2;            /* 图标线条粗细 */
  /* 🐕 */ --wxo-label: #7A7A7A;            /* 下面的字 */
  /* 🐕 */ --wxo-label-size: 12px;
  /* 🐕 */ --wxo-label-gap: 8px;            /* 字离方块的距离 */
  /* 🐕 */ --wxo-inset: 12px;               /* 四列往中间收，越大越挤 */
  /* 🐕 */ --wxo-line: rgba(0, 0, 0, 0.12); /* 输入框和面板之间的细线 */
  /* 🐕 */ --wxo-dot-on: #7F7F7F;           /* 当前页圆点 */
  /* 🐕 */ --wxo-dot-off: #D6D6D6;          /* 其他页圆点 */
  /* 🐕 */ --wxo-dot-y: calc(100% - 44px);  /* 圆点位置，44 越大越靠上 */
  --wxo-row-h: calc(var(--wxo-tile) + var(--wxo-label-gap) + var(--wxo-label-size) * 1.4);
}

/* 页码进度（给跟着滑动的圆点用） */
@property --wxo-p {
  syntax: "<number>";
  inherits: false;
  initial-value: 0;
}
@keyframes wxo-page {
  from { --wxo-p: 0; }
  to   { --wxo-p: 1; }
}

/* --- 1. 菜单打开：底栏下面让出面板高度，输入框整体被顶上去 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .input-area-custom:has(.more-options-popup) {
  /* 🐕 */ --wxo-gap: var(--wxb-top);   /* 输入框离面板分隔线的距离 */
  --wxb-home: calc(var(--wxo-h) + var(--wxo-gap));
  --wxb-bottom: calc(var(--wxo-h) + var(--wxo-gap));
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k):not(#_k) .input-area-custom:has(.more-options-popup):has(.input-reply-preview-bar) {
  --wxb-bottom: calc(var(--wxo-h) + var(--wxo-gap) + var(--wxr-h) + var(--wxr-gap));
}
/* 菜单抬到 9999 只在聊天页里面比，不会跑到设置页上面去 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) {
  isolation: isolate !important;
}
/* 菜单外面那几层（包括功能键）不当定位基准，面板才能按整个底栏铺满整宽 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .input-area-custom *:has(.more-options-popup) {
  position: static !important;
}

/* --- 2. 面板本体：贴底栏底部，整宽，横向翻页 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .input-area-custom .more-options-popup.more-options-popup {
  position: absolute !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  top: auto !important;
  width: auto !important;
  height: var(--wxo-h) !important;
  max-height: none !important;
  min-height: 0 !important;
  box-sizing: border-box !important;
  margin: 0 !important;
  padding: var(--wxo-pad-top) 0 0 !important;

  display: grid !important;
  grid-template-columns: none !important;
  grid-template-rows: repeat(2, var(--wxo-row-h)) !important;
  grid-auto-flow: column !important;
  grid-auto-columns: 25% !important;
  row-gap: var(--wxo-row-gap) !important;
  column-gap: 0 !important;
  align-content: start !important;

  overflow-x: auto !important;
  overflow-y: hidden !important;
  overscroll-behavior: contain !important;
  touch-action: pan-x !important;
  scroll-snap-type: x mandatory !important;
  scrollbar-width: none !important;
  -webkit-overflow-scrolling: touch !important;

  background: transparent !important;
  backdrop-filter: none !important;
