  white-space: nowrap !important;
}
/* 左边那排按钮平均铺开，不用写死的 24px 间距，窄屏也挤得下 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k):not(#_k) .input-area-custom:not(:has(.input-box-custom)) > div > div:first-child {
  flex: 1 1 auto !important;
  min-width: 0 !important;
  justify-content: space-between !important;
  gap: 0 !important;
  margin-right: 14px !important;
}
