/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ Account-英文  糯叽机 by 小真  */
/* 用QQ模式，改壁纸改字号改错位等搜❎❎部分*/

/* ==========================================================================
   全局变量定义区 (三大模块）
   ========================================================================== */
:root {
  /* ── 全局主背景色 (消息区与底部打底完全贯通❎用壁纸删这里) ── */
  --c-main-bg: #fcfdff;                             /* 固定背景基底色：清透霜白 */

  /* ── 模块 1：顶部导航色彩与配置 ── */
  --header-bg: rgba(244, 245, 247, 0.94);            /* 顶部背景：温润透亮冷灰 (#F4F5F7) */
  --header-blur: 20px;                              /* 背景毛玻璃模糊度 */
  --header-border-bottom: 1px solid rgba(0, 0, 0, 0.07); /* 顶部底部分割线 */
  --header-total-height: 110px;                     /* 顶部容器总高度 ❎顶部被压缩优先改大这里*/
  --header-text-main: #52575f;                      /* 标题、返回键核心文字颜色 (柔和炭灰) */
  --header-text-sub: #9ea4ad;                       /* 未选中标签弱化颜色 (冷浅灰) */
  --tab-font-size: 13.5px;                          /* 标签字号 */
  --tab-color-active: #484d55;                      /* Nearby 选中颜色 */
  --tab-color-inactive: #9ea4ad;                    /* 标签未选中颜色 */
  --tab-indicator-color: #9298a2;                   /* 底部高光条颜色 */
  --tab-offset-left: 45px;                          /* 标签左偏移 */
  --header-avatar-size: 48px;                       /* 右侧大头像尺寸 */
  --header-avatar-img: url('https://imgbed.heliar.top/i/bL8aKGFd5LRK9SQW_IMG_3862.jpeg');
  --header-avatar-border: 1px solid rgba(0, 0, 0, 0.08); /* 头像轮廓细线 */

  /* ── 模块 2：底部输入区域色彩与配置 ── */
  --custom-input-bg: #fcfdff;              /* 底栏最外层背景：完全同步消息区大底色 (#FCFDFF) */
  --custom-safe-bottom: calc(18px + var(--nuo-safe-bottom, 0px)); /* 底部安全间距 */
  --custom-card-bg: #f4f5f7;                        /* 输入卡片本体底色：与顶部呼应的浅冷灰 */
  --custom-card-radius: 6px;                        /* 输入卡片圆角 */
  --custom-card-height: 42px;                       /* 输入卡片高度 */
  --custom-plus-color: #7b7e84;                     /* 加号图标：中性冷石灰 */
  --custom-input-text: #2c3038;                     /* 输入框文字：清晰冷墨灰 */
  --custom-placeholder-color: #9ea4ad;              /* 占位提示词 (message) 颜色 */
  --custom-sticker-icon-color: #7b7e84;             /* 右侧三杠图标：中性冷石灰 */
  --custom-action-box-size: 38px;                   /* 外置按钮尺寸 */
  --custom-action-border: #dce0e6;                  /* 外置按钮边框细线 */
  --custom-action-radius: 12px;                     /* 外置按钮圆角 */
  --custom-action-bg: var(--c-main-bg);             /* 发送键/动作键背景底色：融入大底 */
  --custom-action-icon-color: #7b7e84;              /* 外置按钮内部图标 (箭头/方块) 颜色 */

  /* ── 模块 3：聊天消息区域色彩与配置 ── */
  --msg-font-size: 12px;                            /* ❎❎气泡文字字号 */
  --msg-font-size-sub: 11px;                        /* 辅助/次要文字字号 */
  --msg-font-size-quote: 10.5px;                    /* 引用文字字号 */
  --msg-bubble-padding: 5px 8px;                    /* 气泡内边距 */
  --c-text-main: #2c3038;                           /* 正文字体：纯正冷墨灰，字迹清晰 */
  --c-text-muted: #6c727d;                          /* 翻译/引用副文字：细腻钢笔灰 */

  /* 我方气泡：指定微灰冷白 + 清透浅银描边 (彻底无阴影) */
  --c-me-bg: #ffffff;                               /* 我方气泡底色：细腻微灰白纸色 */
  --c-me-border: #d0d4db;                           /* 我方气泡描边：中性质感浅细线 */

  /* 对方气泡：两层极简纯净灰阶 (首条深锚定，后续全浅收拢，告别混乱与脏感) */

--c-ai-step-1: #ebedf2;        /* 首条：比后续只深一点点，干净冷灰 */
--c-ai-step-follow: #f2f4f7;   /* 后续：直接用你方气泡的颜色 */

  /* 辅助与杂项控制 */
  --translation-always-show: 1;
  --translation-btn-display: none;
  --voice-download-display: none;
  --nq-avatar-border: #e5e5e5;                     /* 头像内描边 */
}

/* ==========================================================================
   第一部分：顶部导航 (Header)
   ========================================================================== */

/* 顶部容器外层：只在聊天界面生效 */
.glass-header:has(.header-profile-section) {
  background: var(--header-bg) !important;
  backdrop-filter: blur(var(--header-blur)) !important;
  -webkit-backdrop-filter: blur(var(--header-blur)) !important;
  border-bottom: var(--header-border-bottom) !important;
  box-shadow: none !important;
  height: var(--header-total-height) !important;
  position: relative !important;
  display: flex !important;
  align-items: flex-start !important;
  padding-top: calc(env(safe-area-inset-top, 44px) + 2px) !important; /*  整体上下位置：+2px 越大越往下，越小/负数越往上 */
  padding-left: 12px !important; /*  整体左右位置：12px 越大越往右 */
  padding-right: 14px !important; /*  整体右侧留白：14px */
  box-sizing: border-box !important;
}

/* 隐藏原生的聊天角色小头像 */
.glass-header:has(.header-profile-section) .header-avatar-container,
.glass-header:has(.header-profile-section) .chat-header-avatar {
  display: none !important;
}

/* 返回按钮：换用自定义矢量 Mask 图标 */
.glass-header:has(.header-profile-section) .header-btn-back {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  transform: translate(8px, 2px) !important; /* ❎ 返回键位置：第一个数8px=左右(越大越右)，第二个数2px=上下(越大越下，负数往上) */
  cursor: pointer !important;
}

/* 隐藏返回键自带的 SVG */
.glass-header:has(.header-profile-section) .header-btn-back svg {
  display: none !important;
}

/* 载入细线条冷灰返回键箭头 */
.glass-header:has(.header-profile-section) .header-btn-back::before {
  content: "" !important;
  display: block !important;
  width: 22px !important;
  height: 22px !important;
  background-color: var(--header-text-main) !important;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
